"""Fixture records."""


class Fixture:
    def __init__(self, club, goals):
        self.club = club
        self.goals = goals

    def __repr__(self):
        return "Fixture(%r, %r)" % (self.club, self.goals)


ROWS = [('town', 21), ('united', 8), ('town', 30), ('united', 58), ('rovers', 4)]


def load_fixtures():
    """Yield the stored fixtures one at a time."""
    for club, goals in ROWS:
        yield Fixture(club, goals)


def feed_fixtures():
    """Endless feed of fixtures: repeats the stored rows for ever."""
    while True:
        for club, goals in ROWS:
            yield Fixture(club, goals)
